import { ACTION_APPLIES_TO_FIELDS, CUSTOM_PROMPT_ACTION_ID } from './action_types'
import type { ActionAppliesToField, ActionDefinition } from './action_types'
import type { Card, CardHeader, CardTypeConfig } from './data_types'
import { getCardIdPrefix } from './card_identifiers'

/** The kind of item an action entry point is attached to. */
export type ActionContextKind = 'card' | 'diagram' | 'file' | 'folder' | 'merge-conflict' | 'project'

export type ActionContextFilterValueSource =
    'kind' | 'type' | 'state' | 'file' | 'folder' | 'worktree' | 'text'

export interface ActionContextFilterDescriptor {
    key: ActionAppliesToField
    label: string
    supportedContextKinds: ActionContextKind[]
    valueSource: ActionContextFilterValueSource
    validate: (value: string) => string | null
}

/**
 * The selected item an action is evaluated against. `appliesTo` keys are matched
 * field-by-field against this object, so every matchable property is a string.
 */
export interface ActionContext {
    /** Stable card identity used for activity ownership. */
    cardInternalId?: string
    /** Title of the selected card, used for placeholder resolution. */
    title?: string
    /** Card/file type derived from the id prefix, e.g. `feature`. */
    type?: string
    /** Card state / status, e.g. `design`. */
    state?: string
    /** Path to the markdown file, used for placeholder resolution. */
    file?: string
    /** Folder name for folder contexts. */
    folder?: string
    /** Selected conflicted repository-relative path. */
    conflictFile?: string
    /** Newline-separated conflicted repository-relative paths. */
    conflictFiles?: string
    /** Active desktop conflict session binding. */
    conflictSessionId?: string
    /** Stable diagram record identity. */
    diagramId?: string
    /** Reviewed diagram change instructions captured for one agent handoff. */
    diagramChanges?: string
    /** Stable identity of reviewed diagram changes captured for one agent handoff. */
    diagramChangeSetId?: string
    /** Stable identity of the selected interactive SVG item. */
    diagramItemId?: string
    /** Selected interactive SVG item's data-diagram-label value. */
    parentNode?: string
    kind: ActionContextKind
    worktree?: string
    worktreeError?: string
    [key: string]: string | undefined
}

/**
 * Stable identity of the item an action runs against, used to match a popup to its
 * execution and conversation history. Mutable header fields (title, state, worktree)
 * are excluded on purpose: a run that edits its own card must keep the same identity.
 */
export function actionContextIdentity(context: ActionContext): string {
    if (context.kind === 'project') return 'project'
    if (context.kind === 'diagram') {
        const reviewedContext = context.diagramChanges !== undefined || context.diagramChangeSetId !== undefined
        if (reviewedContext && (!context.diagramId || !context.diagramChanges || !context.diagramChangeSetId)) {
            throw new Error('Reviewed diagram identity requires diagram, change-set, and change values')
        }

        return `diagram�${context.type ?? ''}�${context.diagramId ?? ''}�${context.diagramItemId ?? context.diagramChangeSetId ?? ''}`
    }
    if (context.kind === 'folder') return `folder�${context.folder ?? ''}`
    if (context.kind === 'merge-conflict') {
        return `merge-conflict�${context.conflictSessionId ?? ''}�${context.conflictFile ?? ''}`
    }

    return `${context.kind}�${context.cardInternalId ?? context.file ?? ''}`
}

/** Required-value validation shared by every applicability filter descriptor. */
export function validateActionContextFilterValue(value: string): string | null {
    return value.length > 0 ? null : 'Required value'
}

const ACTION_CONTEXT_FILTER_METADATA: Record<ActionAppliesToField, Omit<ActionContextFilterDescriptor, 'key'>> = {
    file: { label: 'Repository file', supportedContextKinds: ['card', 'file'], valueSource: 
[3030 characters omitted]
tion context for a folder node in the tree. */
export function folderContext(folder: string, isSpecial = false): ActionContext {
    const context: ActionContext = { folder, kind: 'folder' }
    if (isSpecial) context.type = folder

    return context
}

/** Build context for actions that run against the opened project rather than a card or file. */
export function projectContext(): ActionContext {
    return { kind: 'project' }
}

/** Build context for a top-level or drill-down diagram action. */
export function diagramContext(type: 'root'): ActionContext
export function diagramContext(type: 'root', diagramId: string, diagramChanges: string, diagramChangeSetId: string): ActionContext
export function diagramContext(type: 'child', diagramId: string, diagramItemId: string, parentNode: string): ActionContext
export function diagramContext(
    type: 'child' | 'root',
    diagramId?: string,
    diagramItemIdOrChanges?: string,
    parentNodeOrChangeSetId?: string,
): ActionContext {
    if (type === 'root') {
        if (
            diagramId === undefined
            && diagramItemIdOrChanges === undefined
            && parentNodeOrChangeSetId === undefined
        ) return { kind: 'diagram', type }
        if (!diagramId || !diagramItemIdOrChanges || !parentNodeOrChangeSetId) {
            throw new Error('Reviewed diagram context requires diagram, change-set, and change values')
        }

        return {
            diagramChanges: diagramItemIdOrChanges,
            diagramChangeSetId: parentNodeOrChangeSetId,
            diagramId,
            kind: 'diagram',
            type,
        }
    }
    if (!diagramId || !diagramItemIdOrChanges || !parentNodeOrChangeSetId) {
        throw new Error('Child diagram context requires diagram, item, and parent-node values')
    }

    return { diagramId, diagramItemId: diagramItemIdOrChanges, kind: 'diagram', parentNode: parentNodeOrChangeSetId, type }
}

/** Add or remove the session assignment used by project-wide popup actions. */
export function projectContextWithWorktree(context: ActionContext, worktree: number | null): ActionContext {
    if (context.kind !== 'project') return context
    if (worktree === null) {
        const unassignedContext = { ...context }
        delete unassignedContext.worktree

        return unassignedContext
    }

    return { ...context, worktree: String(worktree) }
}

/**
 * True when the action is allowed in the given context. An action with no
 * `appliesTo` (like the built-in custom prompt) matches every context; otherwise
 * every `appliesTo` key must equal the same field on the context.
 */
export function actionMatchesContext(action: ActionDefinition, context: ActionContext): boolean {
    if (!action.appliesTo) return true

    return ACTION_APPLIES_TO_FIELDS.every((key) => action.appliesTo?.[key] === undefined || context[key] === action.appliesTo[key])
}

/** All actions that should be shown for a context, preserving load order. */
export function actionsForContext(actions: ActionDefinition[], context: ActionContext): ActionDefinition[] {
    if (context.kind === 'diagram') {
        return actions.filter((action) => (
            !action.builtin
            && action.appliesTo?.kind === 'diagram'
            && actionMatchesContext(action, context)
        ))
    }

    return actions.filter((action) => (!action.builtin || action.id === CUSTOM_PROMPT_ACTION_ID) && actionMatchesContext(action, context))
}

/** Context actions in selector order, with the built-in custom prompt last. */
export function displayActionsForContext(actions: ActionDefinition[], context: ActionContext): ActionDefinition[] {
    const contextActions = actionsForContext(actions, context)
    const customPrompt = contextActions.find(({ id }) => id === CUSTOM_PROMPT_ACTION_ID)
    const configuredActions = contextActions.filter(({ id }) => id !== CUSTOM_PROMPT_ACTION_ID)

    return customPrompt ? [...configuredActions, customPrompt] : configuredActions
}

import RobotOutline from 'mdi-material-ui/RobotOutline'
import { useEffect } from 'react'
import { projectContext } from '../../data/action_context'
import { cardPopupService } from '../../services/card_popup_service'
import { dataService } from '../../services/data/data_service'
import { dialogService } from '../../services/dialog_service'
import { useProjectAgentState } from '../hooks/use_agent_acknowledgements'
import { useActiveActionRunsForContext } from '../hooks/use_action_runs'
import { AgentFabPresentation } from './agent_fab_presentation'
import { resolveAgentFabState } from './agent_fab_state'

const PROJECT_CONTEXT = projectContext()

/** Project-wide free-form agent launcher, movable anywhere in application viewport. */
export function AgentChatFab() {
    const agentState = useProjectAgentState()
    const activeRuns = useActiveActionRunsForContext(PROJECT_CONTEXT)
    const state = resolveAgentFabState(activeRuns, agentState)
    const handleActivate = (nextAnchorElement: HTMLElement) => cardPopupService.toggleAction(PROJECT_CONTEXT, nextAnchorElement)
    const handleDragStart = () => cardPopupService.closeAction(PROJECT_CONTEXT)

    useEffect(() => {
        void dataService.listAgentConversations(PROJECT_CONTEXT).catch((error: unknown) => {
            dialogService.error(error, { fallbackMessage: 'Could not load project agent conversations' })
        })
    }, [])

    return (
        <AgentFabPresentation
            icon={<RobotOutline />}
            labelPrefix="Project agent"
            onActivate={handleActivate}
            onDragStart={handleDragStart}
            runningDescription={agentState === 'running' ? 'Agent is running' : 'Action is running'}
            state={state}
        />
    )
}

import { Stack } from '@mui/material'

import type { ActionRunBindingStore } from '../run/state/action_run_binding_store'
import type { ActionUsageValuesService } from '../run/popup/action_usage_values_service'
import type { ActionConversationSearchService } from './search/action_conversation_search_service'

interface ActionConversationChatProps {
    actionId: string
    bindingStore: ActionRunBindingStore
    context: ActionContext
    popupEntryId?: string
    popupVisible?: boolean
    searchService: ActionConversationSearchService
    store: ActionConversationStore
    usageValuesService?: ActionUsageValuesService
}

/** Conversation surface; owns selection, live-run, visibility, and acknowledgement subscriptions. */
export function ActionConversationChat(
    {actionId, bindingStore, context, popupEntryId, popupVisible, searchService, store, usageValuesService}: ActionConversationChatProps,
) {
    const selectAcknowledgementConversation = useMemo(() => createAcknowledgementConversationSelector(), [])
    const commands = useMemo(
        () => new ActionConversationCommandService(actionId, context, store),
        [actionId, context, store],
    )
    const boundRunId = useBoundRunId(bindingStore)
    const liveConversation = useRunSelector(boundRunId, selectAcknowledgementConversation)
    const { selectedConversation } = useSyncExternalStore(store.subscribe, store.getSnapshot, store.getSnapshot)
    const conversation = resolveDisplayedConversation(liveConversation, selectedConversation)
    const scope = context.cardInternalId ?? null
    const visible = !!popupEntryId && !!popupVisible && !!conversation

    useEffect(() => {
        if (!popupEntryId || !conversation) return undefined

        agentAcknowledgementService.setConversationVisible(popupEntryId, scope, actionId, conversation, visible)

        return () => agentAcknowledgementService.setConversationVisible(
            popupEntryId, scope, actionId, conversation, false,
        )
    }, [actionId, conversation, popupEntryId, scope, visible])

    return (
        <Stack spacing={1} sx={{ flex: 1, minHeight: 0 }}>
            <ActionConversationTranscript
                bindingStore={bindingStore}
                commands={commands}
                searchService={searchService}
                store={store}
            />
            <ConversationMetaInfo bindingStore={bindingStore} store={store} usageValuesService={usageValuesService} />
        </Stack>
    )
}

import { Stack } from '@mui/material'
import type { ActionContext } from '../../../../data/action_context'
import type { ActionDefinition } from '../../../../data/action_types'
import { useBoundRunId, useRunSelector } from '../../../hooks/use_action_runs'
import { ActionAgentApprovals } from '../../agent/action_agent_approvals'
import { ActionPromptOwner } from '../../agent/action_prompt_owner'
import { ActionConversationChat } from '../../conversation/action_conversation_chat'
import { ActionLogErrorOwner } from '../../conversation/errors/action_log_error_owner'
import type { ActionPopupRuntime } from './action_popup_types'

interface ActionAgentInteractionProps {
    action: ActionDefinition
    assignmentContext: ActionContext
    popupEntryId?: string
    popupVisible?: boolean
    runtime: ActionPopupRuntime
}

/** Agent interaction surface, including agent children started by command actions. */
export function ActionAgentInteraction(props: ActionAgentInteractionProps) {
    const { action, assignmentContext, popupEntryId, popupVisible, runtime } = props
    const {
        bindingStore, conversationSearchService, conversationStore, historyStore, inputStore, resultStore,
        runValidationError, scheduleStore, settingsStore, usageValuesService,
    } = runtime
    const boundRunId = useBoundRunId(bindingStore)
    const activeActionType = useRunSelector(boundRunId, (run) => run?.activeActionType ?? null)
    const visible = action.type === 'agent' || activeActionType === 'agent'
    const displayedUsageValuesService = action.type === 'agent'
        && (assignmentContext.kind === 'project'
            || (assignmentContext.kind === 'card' && !!assignmentContext.file && !!assignmentContext.cardInternalId))
        ? usageValuesService
        : undefined

    if (!visible) return null

    return (
        <Stack sx={{ display: 'contents' }}>
            <Stack spacing={1} sx={{ flex: 1, minHeight: 0 }}>
                <ActionLogErrorOwner bindingStore={bindingStore} resultStore={resultStore} />
                <ActionConversationChat
                    actionId={action.id}
                    bindingStore={bindingStore}
                    context={assignmentContext}
                    popupEntryId={popupEntryId}
                    popupVisible={popupVisible}
                    searchService={conversationSearchService}
                    store={conversationStore}
                    usageValuesService={displayedUsageValuesService}
                />
                <ActionPromptOwner
                    action={action}
                    bindingStore={bindingStore}
                    context={assignmentContext}
                    conversationStore={conversationStore}
                    historyStore={historyStore}
                    inputStore={inputStore}
                    questionsEnabled
                    settingsStore={settingsStore}
                    resultStore={resultStore}
                    runValidationError={runValidationError}
                    scheduleStore={scheduleStore}
                />
                <ActionAgentApprovals bindingStore={bindingStore} />
            </Stack>
        </Stack>
    )
}

